#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

void search(const vector<long long>& weights, int position,
                     long long sum, long long total_sum,
                     long long& best) {
    if (position == static_cast<int>(weights.size())) {
        long long diff = total_sum - 2 * sum;
        if (diff < 0) {
            diff = -diff;
        }
        best = min(best, diff);
        return;
    }

    search(weights, position + 1, sum, total_sum, best);
    search(weights, position + 1,
                    sum + weights[position], total_sum, best);
}

long long min_diff(const vector<long long>& weights) {
    long long total_sum = 0;
    for (long long w : weights) {
        total_sum += w;
    }
    long long best = total_sum;
    search(weights, 0, 0, total_sum, best);
    return best;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> weights(n);
    for (long long& w : weights) {
        cin >> w;
    }
    cout << min_diff(weights) << '\n';
    return 0;
}

